create table if not exists sourcecubes.provider_runtime_readiness (
 provider_code text primary key references ecology.ssr_scientific_data_providers(provider_code), deployment_state text not null default 'UNKNOWN', credential_state text not null default 'UNKNOWN', upstream_runtime_state text not null default 'NOT_VALIDATED', evidence_state text not null default 'NO_RUNTIME_EVIDENCE', canonical_authority_state text not null default 'NONCANONICAL', last_validated_at timestamptz, evidence_reference text, notes text, updated_at timestamptz not null default now());
on conflict(provider_code) do update set deployment_state=excluded.deployment_state,credential_state=excluded.credential_state,upstream_runtime_state=excluded.upstream_runtime_state,evidence_state=excluded.evidence_state,canonical_authority_state=excluded.canonical_authority_state,last_validated_at=excluded.last_validated_at,evidence_reference=excluded.evidence_reference,notes=excluded.notes,updated_at=now();
create or replace view sourcecubes.provider_runtime_readiness_dashboard as select r.provider_code,p.provider_name,p.domain,r.deployment_state,r.credential_state,r.upstream_runtime_state,r.evidence_state,r.canonical_authority_state,r.last_validated_at,r.evidence_reference,r.notes from sourcecubes.provider_runtime_readiness r join ecology.ssr_scientific_data_providers p using(provider_code) order by case r.provider_code when 'W3W' then 1 when 'OT-POINT' then 2 when 'OT-SRTM15PLUS' then 3 when 'OT-GEBCO' then 4 when 'GEBCO-SOURCE' then 5 when 'GOOGLE-ELEV' then 6 when 'MAPBOX-TERRAIN' then 7 else 99 end;
comment on table sourcecubes.provider_runtime_readiness is 'Controlled distinction between deployment, credential evidence, upstream runtime validation, evidence persistence, and canonical authority. Never infer one state from another.';
